<?php require __DIR__ . '/connect.php'; header('Content-Type: application/json'); $email=filter_input(INPUT_GET,'email',FILTER_VALIDATE_EMAIL); if(!$email){echo json_encode(['available'=>false]);exit;} $stmt=$mysqli->prepare('SELECT id FROM users WHERE email=?'); $stmt->bind_param('s',$email); $stmt->execute(); $stmt->store_result(); echo json_encode(['available'=>$stmt->num_rows===0]); ?>
